using LigaVolley.Domain.MatchSheets;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace LigaVolley.Infrastructure.Persistence.Configurations;

internal sealed class MatchLineupConfiguration:IEntityTypeConfiguration<MatchLineup>{public void Configure(EntityTypeBuilder<MatchLineup>b){b.ToTable("MATCH_LINEUP","dbo");b.HasKey(x=>x.MatchLineupId);b.Property(x=>x.MatchLineupId).HasColumnName("match_lineup_id").UseIdentityColumn();b.Property(x=>x.MatchSetId).HasColumnName("match_set_id");b.Property(x=>x.MatchTeamId).HasColumnName("match_team_id");b.HasOne(x=>x.MatchSet).WithMany(x=>x.Lineups).HasForeignKey(x=>x.MatchSetId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.MatchTeam).WithMany().HasForeignKey(x=>x.MatchTeamId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.MatchSetId,x.MatchTeamId}).IsUnique().HasDatabaseName("UQ_MATCH_LINEUP_team");}}
internal sealed class MatchLineupPositionConfiguration:IEntityTypeConfiguration<MatchLineupPosition>{public void Configure(EntityTypeBuilder<MatchLineupPosition>b){b.ToTable("MATCH_LINEUP_POSITION","dbo",t=>t.HasCheckConstraint("CK_MATCH_LINEUP_POSITION_position","[position] IN ('P1','P2','P3','P4','P5','P6')"));b.HasKey(x=>x.MatchLineupPositionId);b.Property(x=>x.MatchLineupPositionId).HasColumnName("match_lineup_position_id").UseIdentityColumn();b.Property(x=>x.MatchLineupId).HasColumnName("match_lineup_id");b.Property(x=>x.Position).AsSql("position",2);b.Property(x=>x.MatchPlayerId).HasColumnName("match_player_id");b.HasOne(x=>x.MatchLineup).WithMany(x=>x.Positions).HasForeignKey(x=>x.MatchLineupId).OnDelete(DeleteBehavior.Cascade);b.HasOne(x=>x.MatchPlayer).WithMany().HasForeignKey(x=>x.MatchPlayerId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.MatchLineupId,x.Position}).IsUnique();b.HasIndex(x=>new{x.MatchLineupId,x.MatchPlayerId}).IsUnique();}}
internal sealed class MatchEventConfiguration:IEntityTypeConfiguration<MatchEvent>{public void Configure(EntityTypeBuilder<MatchEvent>b){b.ToTable("MATCH_EVENT","dbo",t=>{t.HasCheckConstraint("CK_MATCH_EVENT_status","[status] IN ('ACTIVE','CANCELLED')");t.HasCheckConstraint("CK_MATCH_EVENT_sequence","[sequence_number] > 0");});b.HasKey(x=>x.MatchEventId);b.Property(x=>x.MatchEventId).HasColumnName("match_event_id").UseIdentityColumn();b.Property(x=>x.EventUuid).HasColumnName("event_uuid");b.Property(x=>x.MatchSheetId).HasColumnName("match_sheet_id");b.Property(x=>x.MatchSetId).HasColumnName("match_set_id");b.Property(x=>x.EventType).AsSql("event_type",30);b.Property(x=>x.SequenceNumber).HasColumnName("sequence_number");b.Property(x=>x.Side).AsNullableSql("side",10);b.Property(x=>x.MatchPlayerId).HasColumnName("match_player_id");b.Property(x=>x.OccurredAt).HasColumnName("occurred_at");b.Property(x=>x.Status).AsSql("status",20);b.Property(x=>x.RelatedEventId).HasColumnName("related_event_id");b.HasOne(x=>x.MatchSheet).WithMany(x=>x.Events).HasForeignKey(x=>x.MatchSheetId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.MatchSet).WithMany().HasForeignKey(x=>x.MatchSetId).OnDelete(DeleteBehavior.Restrict);b.HasOne<MatchPlayer>().WithMany().HasForeignKey(x=>x.MatchPlayerId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.RelatedEvent).WithMany().HasForeignKey(x=>x.RelatedEventId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.EventUuid).IsUnique().HasDatabaseName("UQ_MATCH_EVENT_uuid");b.HasIndex(x=>new{x.MatchSheetId,x.SequenceNumber}).IsUnique().HasDatabaseName("UQ_MATCH_EVENT_sequence");}}
internal sealed class MatchSubstitutionConfiguration:IEntityTypeConfiguration<MatchSubstitution>{public void Configure(EntityTypeBuilder<MatchSubstitution>b){b.ToTable("MATCH_SUBSTITUTION","dbo");b.HasKey(x=>x.MatchSubstitutionId);b.Property(x=>x.MatchSubstitutionId).HasColumnName("match_substitution_id").UseIdentityColumn();b.Property(x=>x.SubstitutionUuid).HasColumnName("substitution_uuid");b.Property(x=>x.MatchSetId).HasColumnName("match_set_id");b.Property(x=>x.MatchTeamId).HasColumnName("match_team_id");b.Property(x=>x.PlayerOutMatchPlayerId).HasColumnName("player_out_match_player_id");b.Property(x=>x.PlayerInMatchPlayerId).HasColumnName("player_in_match_player_id");b.Property(x=>x.LineupPosition).AsSql("lineup_position",2);b.Property(x=>x.OccurredAt).HasColumnName("occurred_at");b.HasOne(x=>x.MatchSet).WithMany(x=>x.Substitutions).HasForeignKey(x=>x.MatchSetId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.MatchTeam).WithMany().HasForeignKey(x=>x.MatchTeamId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.PlayerOut).WithMany().HasForeignKey(x=>x.PlayerOutMatchPlayerId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.PlayerIn).WithMany().HasForeignKey(x=>x.PlayerInMatchPlayerId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.SubstitutionUuid).IsUnique();}}
internal sealed class MatchLiberoReplacementConfiguration:IEntityTypeConfiguration<MatchLiberoReplacement>{public void Configure(EntityTypeBuilder<MatchLiberoReplacement>b){b.ToTable("MATCH_LIBERO_REPLACEMENT","dbo");b.HasKey(x=>x.MatchLiberoReplacementId);b.Property(x=>x.MatchLiberoReplacementId).HasColumnName("match_libero_replacement_id").UseIdentityColumn();b.Property(x=>x.ReplacementUuid).HasColumnName("replacement_uuid");b.Property(x=>x.MatchSetId).HasColumnName("match_set_id");b.Property(x=>x.MatchTeamId).HasColumnName("match_team_id");b.Property(x=>x.LiberoMatchPlayerId).HasColumnName("libero_match_player_id");b.Property(x=>x.ReplacedMatchPlayerId).HasColumnName("replaced_match_player_id");b.Property(x=>x.LineupPosition).AsSql("lineup_position",2);b.Property(x=>x.EnteredAt).HasColumnName("entered_at");b.Property(x=>x.ExitedAt).HasColumnName("exited_at");b.HasOne(x=>x.MatchSet).WithMany(x=>x.LiberoReplacements).HasForeignKey(x=>x.MatchSetId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.MatchTeam).WithMany().HasForeignKey(x=>x.MatchTeamId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Libero).WithMany().HasForeignKey(x=>x.LiberoMatchPlayerId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Replaced).WithMany().HasForeignKey(x=>x.ReplacedMatchPlayerId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.ReplacementUuid).IsUnique();b.HasIndex(x=>new{x.MatchSetId,x.LiberoMatchPlayerId}).IsUnique().HasFilter("[exited_at] IS NULL").HasDatabaseName("UX_MATCH_LIBERO_REPLACEMENT_active");}}
internal sealed class MatchTimeoutConfiguration:IEntityTypeConfiguration<MatchTimeout>{public void Configure(EntityTypeBuilder<MatchTimeout>b){b.ToTable("MATCH_TIMEOUT","dbo",t=>t.HasCheckConstraint("CK_MATCH_TIMEOUT_number","[timeout_number] BETWEEN 1 AND 2"));b.HasKey(x=>x.MatchTimeoutId);b.Property(x=>x.MatchTimeoutId).HasColumnName("match_timeout_id").UseIdentityColumn();b.Property(x=>x.TimeoutUuid).HasColumnName("timeout_uuid");b.Property(x=>x.MatchSetId).HasColumnName("match_set_id");b.Property(x=>x.MatchTeamId).HasColumnName("match_team_id");b.Property(x=>x.TimeoutNumber).HasColumnName("timeout_number");b.Property(x=>x.OccurredAt).HasColumnName("occurred_at");b.HasOne(x=>x.MatchSet).WithMany(x=>x.Timeouts).HasForeignKey(x=>x.MatchSetId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.MatchTeam).WithMany().HasForeignKey(x=>x.MatchTeamId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.TimeoutUuid).IsUnique();b.HasIndex(x=>new{x.MatchSetId,x.MatchTeamId,x.TimeoutNumber}).IsUnique().HasDatabaseName("UQ_MATCH_TIMEOUT_number");}}
